INSERT INTO crm_mobile_push_device (
    tenant_id, user_id, platform, push_token, app_version, create_time, update_time
) VALUES (
    #{tenantId}, #{userId}, #{platform}, #{pushToken}, #{appVersion}, #{createTime}, #{updateTime}
)
ON CONFLICT (tenant_id, push_token) DO UPDATE SET
    user_id = EXCLUDED.user_id,
    platform = EXCLUDED.platform,
    app_version = EXCLUDED.app_version,
    update_time = EXCLUDED.update_time
